solution.solution.py:
def type_name(value):
    return type(value).__name__


def as_number(text):
    if "." in text:
        return float(text)
    return int(text)


def average(a, b, c):
    return (a + b + c) / 3

unitTests:
@test("type names")
def _():
    check_eq(type_name(42), "int")
    check_eq(type_name(4.2), "float")
    check_eq(type_name("42"), "str")
    check_eq(type_name(True), "bool")
    check_eq(type_name(None), "NoneType")

@test("text to numbers")
def _():
    check_eq(as_number("42"), 42)
    check(type(as_number("42")) is int, "42 should become an int")
    check_eq(as_number("2.5"), 2.5)
    check(type(as_number("3.0")) is float, "3.0 should become a float")
    check_eq(as_number("-7"), -7)

@test("averages are floats")
def _():
    check_eq(average(1, 2, 3), 2.0)
    check(type(average(1, 2, 3)) is float, "the average should be a float")
    check_near(average(1, 2, 2), 1.6666666667, 1e-6)

